INSERT INTO exec_plan_step (plan_id, parent_step_id, title, description, step_type, status, start_date, due_date, is_control_point, sort_order, note, priority)
VALUES
(6, NULL, 'Этап I. Идентификация и верификация процессов Блока ВК', 'Установочная встреча с представителями Службы внутреннего контроля, Службы внутреннего аудита, ДФМ, ДРКНОиПНП. Подготовка проекта перечня процессов Блока ВК. Верификация процессов со стороны владельцев. Инициация внесения изменений в Архитектуру процессов, издание Распоряжения по Банку.', 'stage', 'not_started', '2026-09-30', '2026-12-29', true, 1, 'Ответственные по датам: ЦРПУ (30.09, 30.10), ДРКНОиПНП (16.11), ЦРПУ (29.12).', 'high'),
(6, NULL, 'Этап II. Диагностика и формализация процессов', 'Определение приоритетности процессов для диагностики, выделение 2 пилотных процессов. Интервью с участниками и владельцами пилотных процессов, анализ ВНД. Разработка проектов схем пилотных процессов. Согласование схем с участниками и владельцами. Подготовка текстового описания схем, согласование Порядков по процессам.', 'stage', 'not_started', '2026-10-30', '2027-02-28', true, 2, 'Ключевой этап для нашего Центра: именно здесь формируются схемы процессов, которые в дальнейшем можно автоматизировать/оцифровать.', 'high'),
(6, NULL, 'Этап III. Оптимизация пилотных процессов', 'Формирование рекомендаций по улучшению пилотных процессов. Представление рекомендаций владельцам пилотных процессов и их согласование. Расчёт потенциального эффекта, если он достигается при оптимизации процессов.', 'stage', 'not_started', '2026-12-01', '2027-02-28', true, 3, 'Расчёт потенциального эффекта пересекается с нашей функцией "Оценка эффектов" (F10) — предложить совместную методику расчёта.', 'medium'),
(6, NULL, 'Этап IV. План формализации и оптимизации остальных процессов Блока ВК', 'Формирование сводного плана по формализации и оптимизации всех оставшихся процессов Блока ВК на основе результатов пилотных этапов.', 'task', 'not_started', '2027-01-01', '2027-01-30', true, 4, 'Ответственные: ДРКНОиПНП, ЦРПУ.', 'medium');
